import net.http
import os
import time
import sync
import crypto.sha256
import net.urllib
import regex

const base_url = ''

const domain = urllib.parse(base_url) or { urllib.URL{} }.host

const output_dir = os.join_path(os.getwd(), 'app')

const manifest_file = os.join_path(output_dir, 'manifest.txt')

const metadata_file = os.join_path(output_dir, 'metadata.json')

const user_agent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'

const max_concurrent = 50

const rate_limit_per_host = 0.5

struct Stats {
mut:
  pages_crawled       int
  pages_saved         int
  errors              int
  duplicates_skipped  int
  start_time_unix     i64
  end_time_unix       i64
}

struct Crawler {
  base_url string
  domain   string
  output   string
mut:
  visited           map[string]bool
  queue             []string
  stats             Stats
  host_last_access  map[string]f64
  disallow_rules    []string
  hash_seen         map[string]bool
  mutex             sync.Mutex
  queue_mutex       sync.Mutex
  visited_mutex     sync.Mutex
  host_mutex        sync.Mutex
  disallow_mutex    sync.Mutex
  manifest_mutex    sync.Mutex
  hash_mutex        sync.Mutex
}

fn sanitize_path(url string) string {
  parsed := urllib.parse(url) or { urllib.URL{} }
  mut path := parsed.path.trim_left('/') 
  if path.len == 0 {
    path = 'index'
  }
  mut safe := path.replace('/', '_').replace('\\', '_')
  for c in [u8(`:`) , u8(`*`), u8(`?`), u8(`"`), u8(`<`), u8(`>`), u8(`|`)] {
    safe = safe.replace([c].bytestr(), '_')
  }
  if parsed.raw_query.len > 0 {
    hash := sha256.sum(parsed.raw_query.bytes())
    hash_hex := hex_encode(hash[..])[..8]
    safe = '${safe}_q${hash_hex}'
  }
  if safe.len > 200 {
    safe = safe[..200]
  }
  return '${safe}.txt'
}

fn hex_encode(data []u8) string {
  mut res := []u8{len: data.len * 2}
  hex_chars := '0123456789abcdef'.bytes()
  for i, b in data {
    res[i * 2] = hex_chars[int(b >> 4) & 0x0f]
    res[i * 2 + 1] = hex_chars[int(b) & 0x0f]
  }
  return res.bytestr()
}

fn compute_content_hash(content string) string {
  sum := sha256.sum(content.bytes())
  return hex_encode(sum[..])
}

fn (mut c Crawler) log(msg string) {
  t := time.now().format_ss_milli()
  println('[${t}] ${msg}')
}

fn (mut c Crawler) add_url(url string) {
  if !(url in c.queue) {
    c.queue << url
  }
}

fn (mut c Crawler) get_next_url() ?string {
  if c.queue.len == 0 {
    return none
  }
  url := c.queue[0]
  c.queue = c.queue[1..]
  return url
}

fn (mut c Crawler) mark_visited(url string) bool {
  if url in c.visited {
    return false
  }
  c.visited[url] = true
  return true
}

fn (mut c Crawler) rate_limit(host string) {
  now := f64(time.now().unix_time_milli()) / 1000.0
  last := c.host_last_access[host] or { 0.0 }
  elapsed := now - last
  if elapsed < rate_limit_per_host {
    sleep_dur := (rate_limit_per_host - elapsed)
    time.sleep(time.Duration(i64(sleep_dur * 1000)) * time.millisecond)
    now2 := f64(time.now().unix_time_milli()) / 1000.0
    c.host_last_access[host] = now2
    return
  }
  c.host_last_access[host] = now
}

fn parse_robots_txt(content string) []string {
  mut disallow := []string{}
  lines := content.split_into_lines()
  mut relevant := false
  for line in lines {
    trimmed := line.trim_space()
    if trimmed.len == 0 || trimmed.starts_with('#') {
      continue
    }
    lower := trimmed.to_lower()
    if lower.starts_with('user-agent:') {
      agent := lower.all_after('user-agent:').trim_space()
      if agent == '*' {
        relevant = true
      } else {
        relevant = false
      }
    } else if relevant && lower.starts_with('disallow:') {
      path := trimmed.all_after(':').trim_space()
      if path.len > 0 {
        disallow << path
      }
    }
  }
  return disallow
}

fn (mut c Crawler) load_robots() {
  robots_url := '${c.base_url.trim_right("/")}/robots.txt'
  c.log('Fetching robots.txt: ${robots_url}')
  config := http.FetchConfig{
    url: robots_url
    method: .get
  }
  resp := http.fetch(config) or {
    c.log('Failed to fetch robots.txt')
    return
  }
  if resp.status_code != 200 {
    c.log('robots.txt HTTP status ${resp.status_code}, ignoring')
    return
  }
  disallow := parse_robots_txt(resp.body)
  c.disallow_rules = disallow
  c.log('robots.txt loaded with ${disallow.len} disallow rules')
}

fn (c &Crawler) is_allowed_by_robots(url string) bool {
  if c.disallow_rules.len == 0 {
    return true
  }
  parsed := urllib.parse(url) or { return true }
  path := parsed.path
  for rule in c.disallow_rules {
    if rule == '' {
      continue
    }
    if path.starts_with(rule) {
      return false
    }
  }
  return true
}

fn extract_links_from_html(html_text string, base string) []string {
  mut links := []string{}
  parts := html_text.split('href')
  for i := 1; i < parts.len; i++ {
    part := parts[i]
    mut href := ''
    if part.starts_with('=') || part.starts_with(' =') {
      cleaned := part.trim_left(' =')
      start_char := if cleaned.starts_with('"') { '"' } else if cleaned.starts_with("'") { "'" } else { '' }
      if start_char.len > 0 {
        idx := cleaned.index(start_char) or { continue }
        remaining := cleaned[idx + 1..]
        end_idx := remaining.index(start_char) or { continue }
        href = remaining[..end_idx].trim_space()
      }
    }
    if href.len == 0 {
      continue
    }
    if href.starts_with('#') || href.to_lower().starts_with('javascript:') || href.to_lower().starts_with('mailto:') {
      continue
    }
    mut abs := href
    if !href.contains('://') {
      abs = make_absolute_url(base, href)
    }
    abs = strip_fragment(abs)
    parsed := urllib.parse(abs) or { continue }
    if parsed.scheme !in ['http', 'https'] {
      continue
    }
    if parsed.host != domain {
      continue
    }
    if !(abs in links) {
      links << abs
    }
  }
  return links
}

fn make_absolute_url(base string, href string) string {
  base_parsed := urllib.parse(base) or { return href }
  if href.starts_with('/') {
    return '${base_parsed.scheme}://${base_parsed.host}${href}'
  }
  mut base_path := base_parsed.path
  if !base_path.ends_with('/') {
    idx := base_path.index_last('/') or { -1 }
    if idx >= 0 {
      base_path = base_path[..idx + 1]
    } else {
      base_path = '/'
    }
  }
  return '${base_parsed.scheme}://${base_parsed.host}${base_path}${href}'
}

fn strip_fragment(url string) string {
  idx := url.index('#') or { -1 }
  if idx >= 0 {
    return url[..idx]
  }
  return url
}

fn (mut c Crawler) save_page(url string, content string) {
  hash := compute_content_hash(content)
  if hash in c.hash_seen {
    c.stats.duplicates_skipped++
    c.log('Duplicate content, skipping: ${url}')
    return
  }
  c.hash_seen[hash] = true
  filename := sanitize_path(url)
  filepath := os.join_path(c.output, filename)
  os.write_file(filepath, content) or {
    c.stats.errors++
    c.log('Failed to write file ${filepath}')
    return
  }
  line := '${filename}\t${url}\t${hash}\n'
  mut f := os.open_append(manifest_file) or { return }
  f.writeln(line) or {}
  f.close()
  c.stats.pages_saved++
  c.log('Saved: ${url} -> ${filename}')
}

fn html_to_text(html_text string) string {
  mut cleaned := html_text

  // Remove script, style, and other non-content tags
  cleaned = cleaned.replace_each([
    '<script', '\x00<script',
    '</script>', '</script>\x00',
    '<style', '\x00<style',
    '</style>', '</style>\x00',
    '<head', '\x00<head',
    '</head>', '</head>\x00',
    '<nav', '\x00<nav',
    '</nav>', '</nav>\x00',
    '<footer', '\x00<footer',
    '</footer>', '</footer>\x00',
  ])

  cleaned = cleaned.split('\x00').filter(it.len > 0 && !it.starts_with('<script') && 
    !it.starts_with('<style') && !it.starts_with('<head') && 
    !it.starts_with('<nav') && !it.starts_with('<footer')).join('')

  // Convert headings to markdown-style
  cleaned = cleaned.replace_each([
    '<h1>', '\n# ',
    '</h1>', '\n\n',
    '<h2>', '\n## ',
    '</h2>', '\n\n',
    '<h3>', '\n### ',
    '</h3>', '\n\n',
    '<h4>', '\n#### ',
    '</h4>', '\n',
    '<h5>', '\n##### ',
    '</h5>', '\n',
    '<h6>', '\n###### ',
    '</h6>', '\n',
  ])

  // Convert links to markdown [text](url)
  mut re_links := regex.regex_opt("]*href=[\"']([^\"']+)[\"'][^>]*>([^<]*)") or { 
    cleaned = cleaned 
    cleaned
  }
  cleaned = re_links.replace_by_fn(cleaned, fn (re regex.RE, text string, start int, end int) string {
    return '[$2]($1)'
  })

  // Convert lists
  cleaned = cleaned.replace_each([
    '<ul>', '\n',
    '</ul>', '\n',
    '<ol>', '\n',
    '</ol>', '\n',
    '<li>', '\n- ',
    '</li>', '',
  ])

  // Paragraph and block separators
  cleaned = cleaned.replace_each([
    '</p>', '\n\n',
    '<p>', '',
    '</div>', '\n',
    '<div>', '',
    '</section>', '\n\n',
    '<section>', '',
    '</article>', '\n\n',
    '<article>', '',
    '<br>', '\n',
    '<br/>', '\n',
    '<br />', '\n',
  ])

  // Decode HTML entities
  cleaned = cleaned.replace_each([
    '&nbsp;', ' ',
    '&amp;', '&',
    '&lt;', '<',
    '&gt;', '>',
    '&quot;', '"',
    '&#39;', "'",
    '&apos;', "'",
    '&mdash;', '—',
    '&ndash;', '–',
  ])

  // Remove all remaining HTML tags
  mut re_tags := regex.regex_opt('<[^>]+>') or { return cleaned }
  cleaned = re_tags.replace(cleaned, '')

  // Clean up whitespace
  cleaned = cleaned.replace('\r\n', '\n').replace('\r', '\n')
  mut re_spaces := regex.regex_opt('[ \t]+') or { return cleaned }
  cleaned = re_spaces.replace(cleaned, ' ')

  // Remove empty lines and normalize spacing
  mut lines := cleaned.split('\n')
  mut result := []string{}
  for line in lines {
    trimmed := line.trim_space()
    if trimmed.len > 0 {
      result << trimmed
    }
  }

  mut final_text := result.join('\n')
  mut re_multi := regex.regex_opt('\n{3,}') or { return final_text }
  final_text = re_multi.replace(final_text, '\n\n')

  return final_text.trim_space()
}

fn (mut c Crawler) fetch_page(url string) ?string {
  if !c.is_allowed_by_robots(url) {
    c.log('Blocked by robots.txt: ${url}')
    return none
  }
  parsed := urllib.parse(url) or { return none }
  host := parsed.host
  c.rate_limit(host)
  config := http.FetchConfig{
    url: url
    method: .get
  }
  resp := http.fetch(config) or {
    c.stats.errors++
    c.log('HTTP error fetching ${url}')
    return none
  }
  if resp.status_code != 200 {
    c.stats.errors++
    c.log('Non-200 status ${resp.status_code} for ${url}')
    return none
  }
  ct := resp.header.get(.content_type) or { '' }.to_lower()
  if !ct.contains('text/html') {
    c.log('Skipping non-HTML ${url}')
    return none
  }
  return resp.body
}

fn (mut c Crawler) worker(id int) {
  c.log('Worker ${id} started')
  for {
    url := c.get_next_url() or { break }
    if !c.mark_visited(url) {
      continue
    }
    c.log('Worker ${id} crawling: ${url}')
    html_text := c.fetch_page(url) or {
      continue
    }
    c.stats.pages_crawled++
    text := html_to_text(html_text)
    if text.len > 0 {
      c.save_page(url, text)
    }
    links := extract_links_from_html(html_text, url)
    for link in links {
      c.add_url(link)
    }
  }
  c.log('Worker ${id} stopped')
}

fn (c &Crawler) save_metadata() {
  duration := if c.stats.end_time_unix > c.stats.start_time_unix {
    c.stats.end_time_unix - c.stats.start_time_unix
  } else {
    0
  }
  meta := '{
  "base_url": "${c.base_url}",
  "domain": "${c.domain}",
  "statistics": {
    "pages_crawled": ${c.stats.pages_crawled},
    "pages_saved": ${c.stats.pages_saved},
    "errors": ${c.stats.errors},
    "duplicates_skipped": ${c.stats.duplicates_skipped}
  },
  "crawl_duration_seconds": ${duration}
}
'
  os.write_file(metadata_file, meta) or {}
}

fn main() {
  if !os.is_dir(output_dir) {
    os.mkdir_all(output_dir) or { panic('failed to create output dir') }
  }
  if os.is_file(manifest_file) {
    os.rm(manifest_file) or {}
  }
  mut crawler := Crawler{
    base_url: base_url
    domain: domain
    output: output_dir
    visited: map[string]bool{}
    queue: []string{}
    stats: Stats{}
    host_last_access: map[string]f64{}
    disallow_rules: []string{}
    hash_seen: map[string]bool{}
  }
  crawler.stats.start_time_unix = time.now().unix_time()
  crawler.log('SUPERMEMORY.AI ULTRA-FAST CRAWLER - STARTING')
  crawler.log('Base URL: ${crawler.base_url}')
  crawler.log('Domain: ${crawler.domain}')
  crawler.log('Output directory: ${crawler.output}')
  crawler.log('Max concurrent workers: ${max_concurrent}')
  crawler.load_robots()
  crawler.add_url(crawler.base_url)
  crawler.worker(0)
  crawler.stats.end_time_unix = time.now().unix_time()
  crawler.save_metadata()
  duration := crawler.stats.end_time_unix - crawler.stats.start_time_unix
  crawler.log('================================================================================')
  crawler.log('CRAWL COMPLETE')
  crawler.log('Pages crawled: ${crawler.stats.pages_crawled}')
  crawler.log('Pages saved: ${crawler.stats.pages_saved}')
  crawler.log('Duplicates skipped: ${crawler.stats.duplicates_skipped}')
  crawler.log('Errors: ${crawler.stats.errors}')
  crawler.log('Duration: ${duration} seconds')
  if duration > 0 {
    rate := f64(crawler.stats.pages_crawled) / f64(duration)
    crawler.log('Pages per second: ${rate:.2f}')
  }
  crawler.log('==')
}

